CREATE TABLE rm_task_events (
 id INTEGER PRIMARY KEY,
 task_id TEXT NOT NULL CHECK(length(task_id) BETWEEN 1 AND 160),
 version INTEGER NOT NULL CHECK(version>0),
 operation TEXT NOT NULL CHECK(length(operation) BETWEEN 1 AND 80),
 reason TEXT CHECK(reason IS NULL OR length(trim(reason)) BETWEEN 1 AND 2000),
 payload_json TEXT NOT NULL CHECK(json_valid(payload_json) AND length(payload_json) BETWEEN 2 AND 1048576),
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160),
 principal TEXT NOT NULL CHECK(length(principal) BETWEEN 1 AND 160),
 created_at TEXT NOT NULL CHECK(length(created_at) BETWEEN 20 AND 30),
 UNIQUE(task_id,version),
 CHECK(json_extract(payload_json,'$.taskId') IS task_id),
 CHECK(json_extract(payload_json,'$.version') IS version)
);
CREATE VIEW rm_current_tasks AS SELECT e.* FROM rm_task_events e JOIN (SELECT task_id,MAX(version) version FROM rm_task_events GROUP BY task_id) c ON c.task_id=e.task_id AND c.version=e.version;
CREATE INDEX rm_task_events_lookup ON rm_task_events(task_id,version DESC);

CREATE TABLE rm_task_board_events (
 id INTEGER PRIMARY KEY,
 board_id TEXT NOT NULL CHECK(length(board_id) BETWEEN 1 AND 160),
 version INTEGER NOT NULL CHECK(version>0),
 payload_json TEXT NOT NULL CHECK(json_valid(payload_json) AND length(payload_json) BETWEEN 2 AND 1048576),
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160),
 principal TEXT NOT NULL CHECK(length(principal) BETWEEN 1 AND 160),
 created_at TEXT NOT NULL CHECK(length(created_at) BETWEEN 20 AND 30),
 UNIQUE(board_id,version),
 CHECK(json_extract(payload_json,'$.boardId') IS board_id),
 CHECK(json_extract(payload_json,'$.version') IS version)
);
CREATE VIEW rm_current_task_boards AS SELECT e.* FROM rm_task_board_events e JOIN (SELECT board_id,MAX(version) version FROM rm_task_board_events GROUP BY board_id) c ON c.board_id=e.board_id AND c.version=e.version;
CREATE INDEX rm_task_board_events_lookup ON rm_task_board_events(board_id,version DESC);

CREATE TABLE rm_task_series_events (
 id INTEGER PRIMARY KEY,
 series_id TEXT NOT NULL CHECK(length(series_id) BETWEEN 1 AND 160),
 version INTEGER NOT NULL CHECK(version>0),
 payload_json TEXT NOT NULL CHECK(json_valid(payload_json) AND length(payload_json) BETWEEN 2 AND 1048576),
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160),
 principal TEXT NOT NULL CHECK(length(principal) BETWEEN 1 AND 160),
 created_at TEXT NOT NULL CHECK(length(created_at) BETWEEN 20 AND 30),
 UNIQUE(series_id,version),
 CHECK(json_extract(payload_json,'$.seriesId') IS series_id),
 CHECK(json_extract(payload_json,'$.version') IS version)
);
CREATE VIEW rm_current_task_series AS SELECT e.* FROM rm_task_series_events e JOIN (SELECT series_id,MAX(version) version FROM rm_task_series_events GROUP BY series_id) c ON c.series_id=e.series_id AND c.version=e.version;
CREATE INDEX rm_task_series_events_lookup ON rm_task_series_events(series_id,version DESC);

CREATE TABLE rm_task_receipts (
 principal TEXT NOT NULL CHECK(length(principal) BETWEEN 1 AND 160),
 idempotency_key TEXT NOT NULL CHECK(length(idempotency_key) BETWEEN 1 AND 160),
 operation TEXT NOT NULL CHECK(length(operation) BETWEEN 1 AND 80),
 payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64 AND payload_hash NOT GLOB '*[^0-9a-f]*'),
 result_json TEXT NOT NULL CHECK(json_valid(result_json) AND length(result_json) BETWEEN 2 AND 2000000),
 created_at TEXT NOT NULL CHECK(length(created_at) BETWEEN 20 AND 30),
 PRIMARY KEY(principal,idempotency_key)
);
CREATE TABLE rm_task_notifications (
 notification_id TEXT PRIMARY KEY CHECK(length(notification_id) BETWEEN 1 AND 160),
 recipient_id TEXT NOT NULL CHECK(length(recipient_id) BETWEEN 1 AND 160),
 task_id TEXT NOT NULL CHECK(length(task_id) BETWEEN 1 AND 160),
 reminder_id TEXT NOT NULL CHECK(length(reminder_id) BETWEEN 1 AND 160),
 slot_key TEXT NOT NULL CHECK(length(slot_key) BETWEEN 1 AND 200),
 payload_json TEXT NOT NULL CHECK(json_valid(payload_json) AND length(payload_json) BETWEEN 2 AND 65536),
 created_at TEXT NOT NULL CHECK(length(created_at) BETWEEN 20 AND 30),
 UNIQUE(recipient_id,task_id,reminder_id,slot_key)
);
CREATE TABLE rm_task_runtime (
 id INTEGER PRIMARY KEY CHECK(id=1),
 last_tick_at TEXT,
 last_error TEXT CHECK(last_error IS NULL OR length(last_error)<=1000),
 lease_owner TEXT CHECK(lease_owner IS NULL OR length(lease_owner)<=160),
 lease_until TEXT
);
